macro_rules! SourceFileDiffs {
    () => {
        # [doc = " The source file lines in difference list form. This matches the form"] # [doc = " used within metadata, which saves space by exploiting the fact that the"] # [doc = " lines list is sorted and individual lines are usually not that long."] # [doc = ""] # [doc = " We read it directly from metadata and only decode it into `Lines` form"] # [doc = " when necessary. This is a significant performance win, especially for"] # [doc = " small crates where very little of `std`'s metadata is used."] # [derive (Clone)] pub struct SourceFileDiffs { # [doc = " Always 1, 2, or 4. Always as small as possible, while being big"] # [doc = " enough to hold the length of the longest line in the source file."] # [doc = " The 1 case is by far the most common."] bytes_per_diff : usize , # [doc = " The number of diffs encoded in `raw_diffs`. Always one less than"] # [doc = " the number of lines in the source file."] num_diffs : usize , # [doc = " The diffs in \"raw\" form. Each segment of `bytes_per_diff` length"] # [doc = " encodes one little-endian diff. Note that they aren't LEB128"] # [doc = " encoded. This makes for much faster decoding. Besides, the"] # [doc = " bytes_per_diff==1 case is by far the most common, and LEB128"] # [doc = " encoding has no effect on that case."] raw_diffs : Vec < u8 > , }
    };
}

SourceFileDiffs!()